mapper.select:
SELECT c.warehouse_id, s.member_id, SUM(wb.waybill_price) as total_freight_cost, COUNT(wb.waybill_id) as waybill_cnt
FROM waybill wb, outbound ob, orders o, stock s, cell c
WHERE ob.outbound_id = wb.outbound_id AND ob.order_id = o.order_id AND o.stock_id = s.stock_id AND s.cell_id = c.cell_id AND DATE(wb.reg_date) = #{baseDate}
GROUP BY c.warehouse_id, s.member_id
ORDER BY warehouse_id ASC LIMIT #{_skiprows}, #{_pagesize};
